const resposta = $('Obter token').first().json ?? {};
const status = Number(resposta.statusCode ?? 0);
const motivo = String(resposta.body?.errors?.motivo ?? '');
const PEDE_REAUTORIZACAO = new Set(['reauth_pending', 'sem_token', 'conexao_revogada']);

let falha;
if (status === 409 && PEDE_REAUTORIZACAO.has(motivo)) {
  falha = { causa: 'reauth_pending', detalhe: `cofre de tokens: ${motivo}; reautorize a conexão` };
} else if (status === 429) {
  falha = { causa: 'limite_de_uso', detalhe: 'cofre de tokens: pedidos de token demais para esta execução', pausa: 'limite_temporario', minutos: 5 };
} else if (status === 0 || status >= 500) {
  falha = { causa: 'api_recusou', detalhe: `cofre de tokens indisponível (HTTP ${status || 'sem resposta'})` };
} else {
  falha = { causa: 'falha_coletor', detalhe: `cofre de tokens recusou o pedido (HTTP ${status}${motivo ? `, ${motivo}` : ''})` };
}

return [{ json: { linhas: [], volumetria: { linhas: 0, bytes: 0, requests: 0, duracaoMs: 0 }, falhas: [falha], avisos: [], requests: 0 } }];

const { fonte, janela } = $json;
const versaoApi = 'v1beta';
const propertyId = String(fonte.externalId).replace(/\D/g, '');
const LINHAS_POR_PAGINA = 100000;

const RECORTES = [
  { tabela: 'padrao', opcional: false, dimensoes: [['sessionDefaultChannelGroup', 'canal']], metricas: [['sessions', 'sessoes'], ['totalUsers', 'usuarios'], ['newUsers', 'novosUsuarios'], ['keyEvents', 'conversoes'], ['totalRevenue', 'receita']] },
  { tabela: 'aquisicao', opcional: false, dimensoes: [['sessionSource', 'fonte'], ['sessionMedium', 'midia'], ['sessionCampaignName', 'campanha'], ['sessionDefaultChannelGroup', 'canal_padrao']], metricas: [['sessions', 'sessoes'], ['engagedSessions', 'sessoes_engajadas'], ['totalUsers', 'usuarios'], ['newUsers', 'novos_usuarios'], ['keyEvents', 'eventos_chave'], ['totalRevenue', 'receita'], ['userEngagementDuration', 'duracao_engajamento_seg']] },
  { tabela: 'pagina', opcional: false, dimensoes: [['pagePath', 'pagina']], metricas: [['screenPageViews', 'visualizacoes'], ['activeUsers', 'usuarios_ativos'], ['sessions', 'sessoes'], ['eventCount', 'eventos'], ['keyEvents', 'eventos_chave'], ['userEngagementDuration', 'duracao_engajamento_seg']] },
  { tabela: 'pagina_entrada', opcional: false, dimensoes: [['landingPage', 'pagina_entrada']], metricas: [['sessions', 'sessoes'], ['engagedSessions', 'sessoes_engajadas'], ['totalUsers', 'usuarios'], ['newUsers', 'novos_usuarios'], ['keyEvents', 'eventos_chave'], ['totalRevenue', 'receita']] },
  { tabela: 'evento', opcional: false, dimensoes: [['eventName', 'evento']], metricas: [['eventCount', 'contagem'], ['totalUsers', 'usuarios'], ['eventValue', 'valor'], ['keyEvents', 'eventos_chave']] },
  { tabela: 'dispositivo', opcional: false, dimensoes: [['deviceCategory', 'categoria_dispositivo'], ['operatingSystem', 'sistema_operacional'], ['browser', 'navegador'], ['platform', 'plataforma']], metricas: [['sessions', 'sessoes'], ['engagedSessions', 'sessoes_engajadas'], ['totalUsers', 'usuarios'], ['newUsers', 'novos_usuarios'], ['keyEvents', 'eventos_chave'], ['totalRevenue', 'receita']] },
  { tabela: 'geo', opcional: false, dimensoes: [['country', 'pais'], ['region', 'regiao'], ['city', 'cidade']], metricas: [['sessions', 'sessoes'], ['engagedSessions', 'sessoes_engajadas'], ['totalUsers', 'usuarios'], ['newUsers', 'novos_usuarios'], ['keyEvents', 'eventos_chave'], ['totalRevenue', 'receita']] },
  { tabela: 'item', opcional: true, dimensoes: [['itemName', 'item']], metricas: [['itemsViewed', 'itens_visualizados'], ['itemsAddedToCart', 'itens_no_carrinho'], ['itemsPurchased', 'itens_comprados'], ['itemRevenue', 'receita_item']] },
];

const inicio = Date.now();
return RECORTES.map((recorte) => {
  const dimensoes = [['date', 'metricDate'], ...recorte.dimensoes];
  return {
    json: {
      inicio,
      versaoApi,
      fonte,
      recorte: { ...recorte, dimensoes },
      url: `https://analyticsdata.googleapis.com/${versaoApi}/properties/${propertyId}:runReport`,
      corpo: {
        dateRanges: [{ startDate: janela.start, endDate: janela.end }],
        dimensions: dimensoes.map(([nome]) => ({ name: nome })),
        metrics: recorte.metricas.map(([nome]) => ({ name: nome })),
        orderBys: dimensoes.map(([nome]) => ({ dimension: { dimensionName: nome } })),
        limit: LINHAS_POR_PAGINA,
        offset: 0,
        returnPropertyQuota: true,
      },
    },
  };
});

const itensDeEntrada = $('Montar requisição').all().map((item) => item.json);
const contexto = itensDeEntrada[0];
const respostas = $input.all().map((item) => item.json);
const requests = respostas.length;
const bytes = respostas.reduce((total, resposta) => total + JSON.stringify(resposta.body ?? {}).length, 0);

const avisos = [];

function devolver(linhas, falhas) {
  return [{
    json: {
      linhas,
      volumetria: { linhas: linhas.length, bytes, requests, duracaoMs: Date.now() - contexto.inicio },
      falhas,
      avisos,
      requests,
      versaoApi: contexto.versaoApi,
    },
  }];
}

const CONFIGURACAO_DO_PROJETO = /SERVICE_DISABLED|accessNotConfigured|has not been used in project/;
const SINAIS_DE_LIMITE = /RESOURCE_EXHAUSTED|RATE_LIMIT|rateLimitExceeded|userRateLimitExceeded|quotaExceeded|dailyLimitExceeded|Quota exceeded|Exhausted|Too many requests/i;
const SINAIS_DE_COTA_DIARIA = /dailyLimitExceeded|quotaExceeded|per day|PerDay|daily|Number of operations/i;
const ESCOPO_INSUFICIENTE = /ACCESS_TOKEN_SCOPE_INSUFFICIENT|insufficient authentication scopes/i;
const PERMISSAO_NEGADA = /PERMISSION_DENIED|caller does not have permission|does not have (sufficient )?permission|insufficientPermissions/i;
function semPermissaoNoRecurso(statusCode, texto) {
  return statusCode === 403 && PERMISSAO_NEGADA.test(texto) && !ESCOPO_INSUFICIENTE.test(texto) && !/DEVELOPER_TOKEN/.test(texto);
}
function mensagemSemAcesso() {
  const alvo = typeof contexto === 'undefined' ? '' : String(contexto?.fonte?.externalId ?? '').split('locations/').pop();
  return `Sem permissão na propriedade ${alvo} — a conta autorizada não acessa esta propriedade`.replace('  ', ' ').slice(0, 500);
}
function falhaDaRecusa(statusCode, erro, detalhe) {
  const texto = JSON.stringify(erro ?? {});
  if (CONFIGURACAO_DO_PROJETO.test(texto)) return { causa: 'api_recusou', detalhe };
  if (statusCode === 429 || SINAIS_DE_LIMITE.test(texto)) {
    return { causa: 'limite_de_uso', detalhe: String(detalhe).slice(0, 500), pausa: SINAIS_DE_COTA_DIARIA.test(texto) ? 'cota_diaria' : 'limite_temporario', minutos: null };
  }
  if (/DEVELOPER_TOKEN/.test(texto)) return { causa: 'api_recusou', detalhe };
  if (semPermissaoNoRecurso(statusCode, texto)) return { causa: 'sem_acesso', detalhe: mensagemSemAcesso() };
  if (statusCode === 401 || statusCode === 403) return { causa: 'reauth_pending', detalhe };
  return { causa: 'api_recusou', detalhe };
}


const falhaDeRede = respostas.find((resposta) => resposta.error);
if (falhaDeRede) {
  const detalhe = falhaDeRede.error?.message ?? String(falhaDeRede.error);
  return devolver([], [{ causa: 'api_recusou', detalhe: `falha de rede: ${detalhe}`.slice(0, 500) }]);
}

const nomesApiOpcionais = itensDeEntrada
  .filter((item) => item.recorte.opcional)
  .flatMap((item) => [...item.recorte.dimensoes, ...item.recorte.metricas].map(([nome]) => nome));
const nomesApiObrigatorios = new Set(itensDeEntrada
  .filter((item) => !item.recorte.opcional)
  .flatMap((item) => [...item.recorte.dimensoes, ...item.recorte.metricas].map(([nome]) => nome)));
const exclusivosDoOpcional = nomesApiOpcionais.filter((nome) => !nomesApiObrigatorios.has(nome));

function recusaDoRecorteOpcional(resposta) {
  if (resposta.statusCode !== 400) return false;
  const erro = Array.isArray(resposta.body) ? resposta.body[0]?.error : resposta.body?.error;
  const texto = JSON.stringify(erro ?? {});
  return exclusivosDoOpcional.some((nome) => texto.includes(nome));
}

const recusada = respostas.find((resposta) => !(resposta.statusCode >= 200 && resposta.statusCode < 300) && !recusaDoRecorteOpcional(resposta));
if (recusada) {
  const erro = Array.isArray(recusada.body) ? recusada.body[0]?.error : recusada.body?.error;
  const detalhe = String(erro?.message || `HTTP ${recusada.statusCode}`).slice(0, 500);
  return devolver([], [falhaDaRecusa(recusada.statusCode, erro, detalhe)]);
}

const motivoDaRecusa = (resposta) => {
  if (resposta?.error) return `falha de rede: ${resposta.error?.message ?? String(resposta.error)}`;
  const erro = Array.isArray(resposta?.body) ? resposta.body[0]?.error : resposta?.body?.error;
  return String(erro?.message || `HTTP ${resposta?.statusCode}`);
};

function coletaIncompleta(recusas) {
  const porTabela = new Map();
  for (const { tabela, resposta } of recusas) {
    const atual = porTabela.get(tabela) ?? { total: 0, motivo: motivoDaRecusa(resposta) };
    porTabela.set(tabela, { ...atual, total: atual.total + 1 });
  }
  return [...porTabela].map(([tabela, { total, motivo }]) => ({
    causa: 'coleta_incompleta',
    detalhe: `${tabela}: ${total > 1 ? `${total} pedidos recusados, ` : ''}${motivo}`.slice(0, 500),
  }));
}

function tabelaDoRecorteRecusado(resposta) {
  const erro = Array.isArray(resposta.body) ? resposta.body[0]?.error : resposta.body?.error;
  const texto = JSON.stringify(erro ?? {});
  const recusado = itensDeEntrada.find((item) => item.recorte.opcional
    && [...item.recorte.dimensoes, ...item.recorte.metricas].some(([nome]) => !nomesApiObrigatorios.has(nome) && texto.includes(nome)));
  return recusado?.recorte.tabela ?? 'recorte_opcional';
}

const incompletas = coletaIncompleta(respostas
  .filter((resposta) => !(resposta.statusCode >= 200 && resposta.statusCode < 300))
  .map((resposta) => ({ tabela: tabelaDoRecorteRecusado(resposta), resposta })));

const LIMITE_DE_PAGINAS = 60;
const PAUSA_DA_COTA_HORARIA = 0.8;
const usoDaCota = (resposta) => {
  const cota = resposta.body?.propertyQuota?.tokensPerProjectPerHour;
  const consumido = Number(cota?.consumed);
  const restante = Number(cota?.remaining);
  return Number.isFinite(consumido) && Number.isFinite(restante) && consumido + restante > 0 ? consumido / (consumido + restante) : null;
};
const maiorUsoDaCota = Math.max(0, ...respostas.map(usoDaCota).filter((uso) => uso !== null));
if (maiorUsoDaCota > PAUSA_DA_COTA_HORARIA) {
  avisos.push({ tipo: 'uso_de_cota', detalhe: `tokensPerProjectPerHour em ${Math.round(maiorUsoDaCota * 100)}%: paginação pausada` });
}
const comLimiar = respostas.filter((resposta) => resposta.body?.metadata?.subjectToThresholding === true).length;
if (comLimiar > 0) avisos.push({ tipo: 'limiar_de_privacidade', detalhe: `${comLimiar} resposta(s) com subjectToThresholding: linhas pequenas podem ter sido omitidas pelo GA4` });
const comOutros = respostas.filter((resposta) => resposta.body?.metadata?.dataLossFromOtherRow === true).length;
if (comOutros > 0) avisos.push({ tipo: 'linhas_agrupadas', detalhe: `${comOutros} resposta(s) com dataLossFromOtherRow: parte das linhas foi agrupada em (other)` });
const paginasPorAssinatura = new Map();
for (const resposta of respostas) {
  const assinatura = (resposta.body?.dimensionHeaders ?? []).map((cabecalho) => cabecalho.name).join(',');
  const acumulado = paginasPorAssinatura.get(assinatura) ?? { paginas: 0, linhas: 0, total: 0 };
  paginasPorAssinatura.set(assinatura, {
    paginas: acumulado.paginas + 1,
    linhas: acumulado.linhas + (resposta.body?.rows?.length ?? 0),
    total: Math.max(acumulado.total, Number(resposta.body?.rowCount ?? 0)),
  });
}
for (const [assinatura, { paginas, linhas: lidas, total }] of paginasPorAssinatura) {
  if (assinatura && lidas < total && (paginas >= LIMITE_DE_PAGINAS || maiorUsoDaCota > PAUSA_DA_COTA_HORARIA)) {
    incompletas.push({ causa: 'coleta_incompleta', detalhe: `${assinatura}: paginação interrompida em ${lidas} de ${total} linhas`.slice(0, 500) });
  }
}

const recortePorAssinatura = new Map(itensDeEntrada.map((item) => [item.recorte.dimensoes.map(([nome]) => nome).join(','), item.recorte]));

function formatarData(bruta) {
  const texto = String(bruta ?? '');
  return texto.length === 8 ? `${texto.slice(0, 4)}-${texto.slice(4, 6)}-${texto.slice(6, 8)}` : null;
}

const linhas = [];
for (const resposta of respostas) {
  const corpo = resposta.body;
  if (!corpo?.rows?.length) continue;
  const assinatura = (corpo.dimensionHeaders ?? []).map((cabecalho) => cabecalho.name).join(',');
  const recorte = recortePorAssinatura.get(assinatura);
  if (!recorte) continue;
  for (const linha of corpo.rows) {
    const dim = linha.dimensionValues ?? [];
    const met = linha.metricValues ?? [];
    const saida = recorte.tabela === 'padrao' ? {} : { _tabela: recorte.tabela };
    recorte.dimensoes.forEach(([, campo], indice) => {
      saida[campo] = campo === 'metricDate' ? formatarData(dim[indice]?.value) : dim[indice]?.value ?? null;
    });
    recorte.metricas.forEach(([, campo], indice) => {
      saida[campo] = Number(met[indice]?.value ?? 0);
    });
    linhas.push(saida);
  }
}

const CAMPOS_DE_ENDERECO = ['pagina', 'pagina_entrada'];
const semConsultaNemAncora = (valor) => (typeof valor === 'string' ? valor.split(/[?#]/)[0] || '/' : valor);
const metricasPorTabela = new Map(itensDeEntrada.map((item) => [item.recorte.tabela, item.recorte.metricas.map(([, campo]) => campo)]));

function agregarEnderecos(brutas) {
  const grupos = new Map();
  const saida = [];
  for (const linha of brutas) {
    const campos = CAMPOS_DE_ENDERECO.filter((campo) => campo in linha);
    if (campos.length === 0) {
      saida.push(linha);
      continue;
    }
    const limpa = { ...linha };
    for (const campo of campos) limpa[campo] = semConsultaNemAncora(limpa[campo]);
    const metricas = metricasPorTabela.get(linha._tabela ?? 'padrao') ?? [];
    const chave = JSON.stringify(Object.entries(limpa).filter(([campo]) => !metricas.includes(campo)));
    const atual = grupos.get(chave);
    if (!atual) {
      grupos.set(chave, limpa);
      saida.push(limpa);
      continue;
    }
    for (const metrica of metricas) atual[metrica] = Number(atual[metrica] ?? 0) + Number(limpa[metrica] ?? 0);
  }
  return saida;
}

const linhasSemConsulta = agregarEnderecos(linhas);

if (linhasSemConsulta.length === 0) return devolver([], incompletas.length > 0 ? incompletas : [{ causa: 'sem_dados_no_periodo', detalhe: null }]);
return devolver(linhasSemConsulta.map((linha) => ({ ...linha, versaoApi: contexto.versaoApi })), incompletas);
